(function() {
  var arr = [];
  var push = function (title, url, num, g, act) {
    var j = { title: title, url: url, style: { layout_flexBasisPercent: num, layout_flexGrow: (g == 0 ? 0 : 1) } };
    if (act) {
      j.action = act.action;
      j.name = act.name || title;
      j.type = act.type;
      j.chars = act.chars;
      j.viewName = act.viewName;
      j.default = act.default;
    }
    arr.push(j);
  };

  push('🍅 番茄小说TS', '', 1, 0);
  var mode = fqModeName(fqGet('mode') || '小说');
  if (mode === '漫画') { mode = '小说'; }

  arr.push({
    title: '模式', url: '', style: { layout_flexBasisPercent: 0.45, layout_flexGrow: 1 },
    type: 'select', name: '模式', chars: FQ_MODE_LIST, default: mode, action: 'java.refreshExplore()'
  });
  push('📥 刷新发现页', '', 0.45, 1, { name: '📥 刷新发现页', type: 'button', action: 'java.refreshExplore()' });

  try {
    var sel = '';
    if (typeof infoMap !== 'undefined' && infoMap) {
      try { sel = String(infoMap['模式'] || ''); } catch (e) { sel = ''; }
    }
    if (sel) mode = fqModeName(sel);
  } catch (e) {}
  fqSet('mode', mode);

  var cats = fqCats(fqCatOf(mode));
  push('📂 ' + fqIconOf(mode) + ' ' + mode + '分类（' + cats.length + '）', '', 1, 0);
  for (var i = 0; i < cats.length; i++) {
    push(cats[i].name, fqExploreUrl(cats[i].id), 0.24, 1, {});
  }
  return JSON.stringify(arr);
})()

