var fqJ_ = null, fqS_ = null, fqC_ = null;

function fqUse(j, s, c) { fqJ_ = j; fqS_ = s; fqC_ = c; }

function fqUseSource(s) { fqS_ = s; }

function fqUseJava(j) { fqJ_ = j; }

var FQ_HOST = 'https://fq.tangsongxs.com';

var FQ_MODES = {
  '小说': { tab: '3',  cat: '1', type: 8 },
  '听书': { tab: '2',  cat: '3', type: 8 },
  '短剧': { tab: '11', cat: '6', type: 4 },
  '漫画': { tab: '5',  cat: '5', type: 64 }
};

var FQ_MODE_LIST = ['小说', '听书', '短剧'];
var FQ_MODE_ICON = { '小说': '📖', '听书': '🎧', '短剧': '🎬', '漫画': '🖼️' };

function fqHost() { return FQ_HOST; }
function fqTabOf(mode)  { var m = FQ_MODES[fqModeName(mode)]; return m ? m.tab  : '3'; }
function fqCatOf(mode)  { var m = FQ_MODES[fqModeName(mode)]; return m ? m.cat  : '1'; }
function fqTypeOf(mode) { var m = FQ_MODES[fqModeName(mode)]; return m ? m.type : 8; }
function fqIconOf(mode) { return FQ_MODE_ICON[fqModeName(mode)] || '📖'; }

function fqModeName(x) {
  var s = String(x == null ? '' : x);
  if (s === '小说' || s === '听书' || s === '短剧' || s === '漫画') return s;
  return '小说';
}

function fqBool(v) { return v === true || String(v) === 'true' || String(v) === '1'; }

function fqState() {
  var d = {};
  try { d = JSON.parse(String((fqS_ && fqS_.getVariable()) || '{}')); } catch (e) {}
  return (d && typeof d === 'object') ? d : {};
}

function fqSave(d) {
  if (!fqS_) return;
  var v = '';
  try { v = JSON.stringify(d); } catch (e) { return; }
  try {
    if (typeof fqS_.putVariable === 'function') fqS_.putVariable(v);
    else fqS_.setVariable(v);
  } catch (e) {}
}

function fqGet(k) {
  var v = fqState()[k];
  return v == null ? '' : v;
}

function fqSet(k, v) {
  var d = fqState();
  d[k] = v;
  fqSave(d);
}

function fqJava() { return fqJ_; }
function fqCache() { return fqC_; }

function fqFetch(url, ttl) {
  var j = fqJava();
  if (!j || !url) return '';
  var c = fqCache();
  if (c) {
    try {
      var hit = String(c.get(url) || '');
      if (hit) return hit;
    } catch (e) {}
  }
  var r = '';
  try { r = String(j.ajax(url) || ''); } catch (e) { r = ''; }
  if (r && c) {
    try {
      if (ttl) c.put(url, r, ttl); else c.put(url, r);
    } catch (e) {}
  }
  return r;
}

function fqCats(tab) {
  var out = [];
  var tabs = [String(tab || '1'), '1'];
  for (var ti = 0; ti < tabs.length; ti++) {
    var raw = fqFetch(FQ_HOST + '/category?tab=' + tabs[ti], 86400);
    var d = null;
    try { d = JSON.parse(raw); } catch (e) { d = null; }
    var td = (d && d.data && d.data.category_tab_data) || {};
    var cells = td.cell_data || [];
    for (var i = 0; i < cells.length; i++) {
      var atoms = cells[i].atom_data || [];
      for (var n = 0; n < atoms.length; n++) {
        var cd = atoms[n].category_data || {};
        if (cd.category_id != null && cd.name) {
          var cid = String(cd.category_id);
          var dup = false;
          for (var k = 0; k < out.length; k++) { if (out[k].id === cid) { dup = true; break; } }
          if (!dup) out.push({ id: cid, name: String(cd.name) });
        }
      }
    }
    if (out.length > 0) break;
  }
  if (out.length === 0) out.push({ id: '1', name: '都市' });
  return out;
}

function fqExploreUrl(cid) {
  var tab = fqCatOf(fqGet('mode') || '小说');
  return FQ_HOST + '/category/landing?tab=' + tab + '&category_id=' + cid + '&offset={{(page-1)*20}}';
}

function fqEncode(s) {
  var j = fqJava();
  var t = String(s == null ? '' : s);
  try { if (j && typeof j.encodeURI === 'function') return j.encodeURI(t); } catch (e) {}
  try { return encodeURIComponent(t); } catch (e2) { return t; }
}

function fqIsVideoType(t) {
  return String(t || '').indexOf('剧') >= 0;
}

function fqModeOf(t) {
  if (fqIsVideoType(t)) return '短剧';
  if (String(t || '').indexOf('漫') >= 0) return '漫画';
  if (String(t || '').indexOf('听') >= 0) return '听书';
  return '小说';
}

function fqBubble(count, bid, iid, para) {
  var num = String(count > 99 ? '99+' : count);
  var bc = fqGet('bubbleColor') || '#8A99A8';
  var tc = fqGet('textColor') || '#F2F5F7';
  var svg = '<svg viewBox="5 14 45 36" xmlns="http://www.w3.org/2000/svg" width="110" height="88">'
    + '<path d="M44 48 Q48 48 48 44 L48 20 Q48 16 44 16 L20 16 Q16 16 16 20 L16 24 S16 28 10 30 Q6 32 10 34 Q16 36 16 38 L16 44 Q16 48 20 48 Z"'
    + ' fill="none" stroke="' + bc + '" stroke-width="0.8"/>'
    + '<text x="32" y="38" text-anchor="middle" font-family="sans-serif" font-weight="600" font-size="18"'
    + ' fill="' + tc + '" dominant-baseline="middle">' + num + '</text></svg>';
  var b64 = '';
  try { b64 = String(fqJava().base64Encode(svg) || ''); } catch (e) { b64 = ''; }
  if (!b64) return '';
  return '<img src="data:image/svg+xml;base64,' + b64 + ',{"style":"text","type":"qd","click":"showCmt.call(this, java, \''
    + bid + '\',\'' + iid + '\',\'' + para + '\')"}">';
}

function fqAddBubbles(content, bid, iid, version) {
  if (!fqBool(fqGet('showPara'))) return content;
  var txt = String(content || '');
  if (!txt || !bid || !iid) return txt;
  var j = fqJava();
  if (!j) return txt;
  var url = FQ_HOST + '/chapter_review?item_id=' + iid + '&book_id=' + bid;
  if (version) url += '&item_version=' + String(version);
  var raw = '';
  try { raw = String(j.ajax(url) || ''); } catch (e) { return txt; }
  var d = null;
  try { d = JSON.parse(raw); } catch (e) { return txt; }
  var idea = (d && d.data && d.data.idea_data) || null;
  if (!idea || typeof idea !== 'object') return txt;
  var paras = txt.replace(/\r/g, '').split('\n');
  for (var i = 0; i < paras.length; i++) {
    var p = paras[i];
    if (!p) continue;
    var info = idea[String(i)];
    if (!info) continue;
    var cnt = parseInt(info.idea_count, 10);
    if (isNaN(cnt) || cnt <= 0) continue;
    paras[i] = p + fqBubble(cnt, bid, iid, String(i));
  }
  return paras.join('\n');
}

function showCmt(a, b, c, d) {
