function fqTrail(list) {
  var s2 = list.join(' | ');
  try { if (typeof source !== 'undefined' && source && source.setVariable) {
    var d2 = {};
    try { d2 = JSON.parse(String(source.getVariable() || '{}')); } catch (e2) { d2 = {}; }
    d2.fqcmt = String(s2).substring(0, 400);
    source.setVariable(JSON.stringify(d2));
  } } catch (e3) {}
}

function fqParseSize(v) {
  if (v == null) return 0;
  if (typeof v === 'number') return isFinite(v) && v > 0 ? Math.floor(v) : 0;
  var s = String(v).replace(/\s+/g, '');
  var m = s.match(/^([0-9]*\.?[0-9]+)([KMGT]?)B?$/i);
  if (!m) return 0;
  var n = parseFloat(m[1]);
  if (!isFinite(n) || n <= 0) return 0;
  var u = m[2].toUpperCase();
  var mul = u === 'K' ? 1024 : (u === 'M' ? 1048576 : (u === 'G' ? 1073741824 : (u === 'T' ? 1099511627776 : 1)));
  return Math.floor(n * mul);
}

function fqVideoStreamJson(itemId, bookId) {
