function fqDrmDecrypt(encKey) {
  var s = String(encKey || '');
  if (!s) return '';
  var j = fqJava(); // 仅用 fqUse 绑定的实例（裸 java 全局可能是 JavaPackage 壳）
  if (!j) return '';
  var raw = '';
  try { raw = String(j.ajax(FQ_HOST + '/drm/decrypt?enc_key=' + fqEncode(s)) || ''); } catch (e3) {}
  if (!raw) return '';
  var d = null;
  try { d = JSON.parse(raw); } catch (e4) { d = null; }
  var key = '';
  try {
    if (d) {
      var dd = (d.data != null) ? d.data : d;
      key = String(dd.decrypted_key || dd.key || dd.decrypt_key || '');
    }
  } catch (e5) { key = ''; }
  if (!key) {
    var m = raw.match(/[0-9a-fA-F]{32}/);
    if (m) key = m[0];
