}

function fqMangaLines(raw) {
  var d = (raw && raw.data) ? raw.data : (raw || {});
  var pg = d.images || d.pages || d.page_list || d.contents || d.item_data || [];
  if (typeof pg === 'string') { try { pg = JSON.parse(pg); } catch (e0) { pg = []; } }
