  for (var i = 0; i < pg.length; i++) {
    var e = pg[i];
    if (e == null) continue;
    var u = (typeof e === 'string') ? e : String(e.image_url || e.url || e.uri || e.webp_url || '');
    if (u) lines.push(u);
  }
  if (!lines.length) {
