function login() {}

function lvState() {
  var d = {};
  try { d = JSON.parse(String(source.getVariable() || '{}')); } catch (e) {}
  return (d && typeof d === 'object') ? d : {};
}

function lvSave(d) {
  var v = '';
  try { v = JSON.stringify(d); } catch (e) { return; }
  try {
    if (typeof source.putVariable === 'function') source.putVariable(v);
    else source.setVariable(v);
  } catch (e) {}
}

function lvRefresh() { try { java.reLoginView(); } catch (e) {} }
function lvToast(m) { try { java.toast(String(m)); } catch (e) {} }

function lvSetMenu(m) {
  var d = lvState(); d.menu = m; lvSave(d); lvRefresh();
}

function lvSetMode(mode) {
  var d = lvState(); d.mode = mode; lvSave(d);
  lvToast('已切换：' + mode);
  lvSetMenu('main');
}

function lvTogglePara() {
  var d = lvState(); d.showPara = !d.showPara; lvSave(d);
  lvToast('段评' + (d.showPara ? '开' : '关'));
  lvRefresh();
}

function lvToggleAudio() {
  var d = lvState();
  d.audioPlay = (d.audioPlay === false) ? true : false; lvSave(d);
  lvToast('听书播放' + (d.audioPlay === false ? '关' : '开'));
  lvRefresh();
}

function lvSummary() {
  var d = lvState(); d.summary = !d.summary; lvSave(d);
  lvToast('章末摘要' + (d.summary ? '开' : '关'));
  lvRefresh();
}

function lvBegin() {
  lvSave({ menu: 'main', mode: '小说', showPara: true, audioPlay: true, summary: false, bookId: '' });
  lvToast('已恢复默认');
  lvRefresh();
}

function lvClean() {
  try { source.setVariable(''); } catch (e) {}
  lvToast('已清空');
  lvRefresh();
}

function lvTest() {
  var m = '';
  try {
    var td = (JSON.parse(String(java.ajax('https://fq.tangsongxs.com/category?tab=1') || '{}')).data || {}).category_tab_data || {};
    var n = 0, cells = td.cell_data || [];
    for (var i = 0; i < cells.length; i++) {
      var atoms = cells[i].atom_data || [];
      for (var k = 0; k < atoms.length; k++) if ((atoms[k].category_data || {}).category_id != null) n++;
    }
    m = '接口正常（' + n + ' 分类）';
  } catch (e) { m = '接口异常：' + e; }
  lvToast(m);
}

function lvAbout() {
  lvToast('番茄小说TS\n'
    + '小说 / 听书 / 短剧，进章节自动播放\n'
    + '搜索前缀：+3小说 +2听书 +11短剧\n'
    + '＋书号(id) 直达详情');
}

function lvStatus() {
  var d = lvState();
  lvToast('模式：' + (d.mode || '小说')
    + '\n段评：' + (d.showPara !== false ? '开' : '关')
    + '｜听书播放：' + (d.audioPlay !== false ? '开' : '关')
    + '｜摘要：' + (d.summary ? '开' : '关'));
}

if (!source.getVariable()) lvBegin();

ruleContent.content:
@js:
fqUse(java, source, cache);
var mode = fqModeName(fqGet('mode') || '小说');
var isVideo = fqIsVideoType(mode);
var isComic = (mode === '漫画');
var isAudio = (mode === '听书');
function qp(re) { var m = String(baseUrl || '').match(re); return m ? m[1] : ''; }
var iid = qp(/item_id=([^&]+)/) || qp(/video_id=([^&]+)/);
var bid = qp(/book_id=([^&]+)/);
var ver = qp(/_v=([^&]+)/);
var raw = result;
if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch (e) { raw = null; } }
if (!raw || !raw.data) {
  result = '⚠️ 正文获取失败\\n' + String(baseUrl || '');
} else if (isComic) {
  var pg = raw.data.images || raw.data.pages || raw.data.page_list || raw.data.contents || raw.data.item_data || [];
  if (typeof pg === 'string') { try { pg = JSON.parse(pg); } catch (e0) { pg = []; } }
  var lines = [];
  for (var pi = 0; pi < pg.length; pi++) {
    var pe = pg[pi];
    if (pe == null) continue;
    var u = (typeof pe === 'string') ? pe : String(pe.image_url || pe.url || pe.uri || pe.webp_url || '');
    if (u) lines.push(u);
  }
  if (!lines.length) {
    lines = fqMangaLines(raw);
  }
  result = lines.length ? lines.join('\\n') : '⚠️ 漫画页解析失败';
} else if (isVideo) {
  var curNow = true;
  try {
    var _bi = Number(book.durChapterIndex), _ci = Number(chapter.index);
    if (!isNaN(_bi) && !isNaN(_ci)) curNow = (_bi === _ci);
  } catch (eg1) {}
  if (!curNow) {
    result = '🎬 本集为视频内容，进入该章即自动打开播放器';
  } else {
    var stream = null;
    try { stream = JSON.parse(String(fqVideoStreamJson(iid, bid) || '{}')); } catch (es) { stream = null; }
    if (!stream || stream.err || !stream.url) {
      result = '⚠️ 视频流解析失败：' + ((stream && stream.err) || '未知');
    } else {
      var epList = [];
      try {
        var tocRaw = String(fqFetch(fqHost() + '/catalog?book_id=' + bid, 3600) || '');
        var tocData = JSON.parse(tocRaw);
        var il = ((tocData && tocData.data && tocData.data.item_data_list) || []);
        for (var ti = 0; ti < il.length; ti++) {
          var it = il[ti];
          if (!it || !it.item_id) continue;
          epList.push({ id: String(it.item_id), t: String(it.title || ('第' + (ti + 1) + '集')) });
        }
      } catch (ecl) {}
      var curIdx = 0;
      for (var ci2 = 0; ci2 < epList.length; ci2++) {
        if (String(epList[ci2].id) === String(iid)) { curIdx = ci2; break; }
      }
      var title = (book && book.name) ? String(book.name) : '视频播放';
      var html = fqCencPlayerHtml(title, stream.url, stream.keyHex, stream.size, epList, curIdx, bid, 'video');
      try { java.startBrowser('about:blank', title, html); } catch (e3) {}
      result = '🎬 ' + title + '\\n播放器已打开，返回键退出后可继续浏览目录\\n（本集时长见播放器内显示）';
    }
  }
} else if (isAudio) {
  var audioOn = fqGet('audioPlay');
  audioOn = !(audioOn === false || audioOn === 'false' || audioOn === '0');
  var curA = true;
  try {
    var _ba = Number(book.durChapterIndex), _ca = Number(chapter.index);
    if (!isNaN(_ba) && !isNaN(_ca)) curA = (_ba === _ca);
  } catch (eg2) {}
  var txt = String((raw.data && raw.data.content) || '');
  var as = null;
  try { as = JSON.parse(String(fqAudioStreamJson(iid, bid) || '{}')); } catch (ea) { as = null; }
  if (curA && audioOn && as && !as.err && as.url) {
    var epA = [];
    try {
      var tocA = JSON.parse(String(fqFetch(fqHost() + '/catalog?book_id=' + bid, 3600) || ''));
      var ilA = ((tocA && tocA.data && tocA.data.item_data_list) || []);
      for (var ai = 0; ai < ilA.length; ai++) {
        var ia = ilA[ai];
        if (!ia || !ia.item_id) continue;
        epA.push({ id: String(ia.item_id), t: String(ia.title || ('第' + (ai + 1) + '集')) });
      }
    } catch (eal) {}
    var ciA = 0;
    for (var ai2 = 0; ai2 < epA.length; ai2++) {
      if (String(epA[ai2].id) === String(iid)) { ciA = ai2; break; }
    }
    var tA = (book && book.name) ? String(book.name) : '音频播放';
    var hA = fqCencPlayerHtml(tA, as.url, as.keyHex, as.size, epA, ciA, bid, 'audio');
    try { java.startBrowser('about:blank', tA, hA); } catch (e4) {}
    result = '🎧 ' + tA + '\\n播放器已打开（返回键退出后阅读文字稿）\\n\\n' + (txt || '');
  } else {
    result = txt ? fqAddBubbles(txt, bid, iid, ver) : '（本章暂无文字正文）';
  }
} else {
  var txt2 = String((raw.data && raw.data.content) || '');
  if (!txt2) {
    result = '（本章暂无文字正文）';
  } else {
    if (fqBool(fqGet('summary'))) {
      try {
        var sj = JSON.parse(String(java.ajax(fqHost() + '/item_summary?item_ids=' + iid + '&book_id=' + bid) || '{}'));
        var sl = (sj && sj.data) || [];
        var st = (sl.length && sl[0]) ? String(sl[0].summary || sl[0].content || sl[0].text || '') : '';
        if (st) txt2 = txt2 + '\\n\\n──────────\\n📝 本章AI摘要\\n' + st.replace(/\\n/g, '\\n');
      } catch (es2) {}
    }
    result = fqAddBubbles(txt2, bid, iid, ver);
  }
}
result;

