(function() {
  fqUse(java, source, cache);
  var d = result;
  if (typeof d === 'string') { try { d = JSON.parse(d); } catch (e) { d = null; } }
  var o = (d && d.data) ? d.data : d;
  var list = null;
  if (o) list = o.items || o.book_info || o.video_info || o.item_data_list;
  if (!list || !list.length) list = (o && (o.book_id || o.series_id)) ? [o] : [];
  var out = [];
  for (var i = 0; i < list.length; i++) {
    var e = list[i];
    if (!e) continue;
    var bid = String(e.book_id || e.series_id || '');
    out.push({
      name: String(e.book_name || e.title || e.book_short_name || ''),
      author: String(e.author || e.copyright || ''),
      bookUrl: fqHost() + '/detail?book_id=' + bid,
      coverUrl: String(e.cover_url || e.cover || e.audio_thumb_url_hd || e.audio_thumb_uri || e.thumb_url || ''),
      intro: String(e.abstract || e.video_desc || e.sub_title || ''),
      lastChapter: String(e.last_chapter_title || ''),
      wordCount: String(e.word_count || e.episode_cnt || ''),
      kind: (function () {
        var ty = String(e.type || '');
        var parts = [];
        if (ty && !/^\d+$/.test(ty)) parts.push(ty);
        if (e.score != null && String(e.score) !== '0') parts.push(String(e.score) + '分');
        return parts.join('｜');
      })(),
      bookId: bid
    });
  }
  var strs = [];
  for (var k = 0; k < out.length; k++) strs.push(JSON.stringify(out[k]));
  return strs;
})()

